<?php
require_once 'db.php'; require_role('vendor'); $vendor_id=(int)$_SESSION['user_id'];
$stmt=$conn->prepare("SELECT COALESCE(SUM(total),0) AS sales, COUNT(*) AS order_count FROM orders WHERE vendor_id=? AND status='completed' AND DATE(created_at)=CURDATE()"); $stmt->bind_param('i',$vendor_id); $stmt->execute(); $salesRow=$stmt->get_result()->fetch_assoc();
$stmt=$conn->prepare('SELECT COALESCE(SUM(amount),0) AS expenses FROM expenses WHERE vendor_id=? AND DATE(created_at)=CURDATE()'); $stmt->bind_param('i',$vendor_id); $stmt->execute(); $expenseTotal=(float)$stmt->get_result()->fetch_assoc()['expenses'];
$profit=(float)$salesRow['sales']-$expenseTotal;
$stmt=$conn->prepare("SELECT m.name,SUM(o.quantity) AS quantity FROM orders o JOIN menu_items m ON m.id=o.menu_id WHERE o.vendor_id=? AND o.status='completed' AND DATE(o.created_at)=CURDATE() GROUP BY m.id,m.name ORDER BY quantity DESC LIMIT 5"); $stmt->bind_param('i',$vendor_id); $stmt->execute(); $top=$stmt->get_result();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Daily report | Mama Ntilie</title><link rel="stylesheet" href="style.css"></head><body><header class="topbar"><a class="brand" href="vendor_dashboard.php">🍲 Mama Ntilie</a><a href="logout.php">Sign out</a></header><main class="page-wrap"><a class="back-link" href="vendor_dashboard.php">← Dashboard</a><span class="eyebrow">DAILY BUSINESS SNAPSHOT</span><h1>Today's report</h1><p class="muted"><?= date('l, d F Y') ?> · Completed sales less recorded expenses</p>
<div class="stat-grid"><div class="stat-card"><span>Completed sales</span><strong><?= money($salesRow['sales']) ?></strong><small><?= (int)$salesRow['order_count'] ?> completed order(s)</small></div><div class="stat-card"><span>Recorded expenses</span><strong><?= money($expenseTotal) ?></strong><small>Expenses entered today</small></div><div class="stat-card"><span>Net result</span><strong class="<?= $profit>=0?'positive':'negative' ?>"><?= money($profit) ?></strong><small><?= $profit>=0?'Positive balance':'Negative balance' ?></small></div></div>
<section class="panel"><h2>Top-selling meals today</h2><?php if($top->num_rows): ?><ol class="top-list"><?php while($dish=$top->fetch_assoc()): ?><li><span><?= e($dish['name']) ?></span><strong><?= (int)$dish['quantity'] ?> sold</strong></li><?php endwhile; ?></ol><?php else: ?><p class="muted">No completed meal sales recorded today yet.</p><?php endif; ?></section><p class="notice">This is a simple operating estimate, not a full accounting statement. It uses completed order totals and expenses entered into the system.</p></main></body></html>
